    missing = []
    for package in packages:
        # Strip version specifiers for simple check
        pkg_name = package.split(">=")[0].split("==")[0].split("<=")[0].strip()
        try:
            pkg_resources.get_distribution(pkg_name)
        except pkg_resources.DistributionNotFound:
            missing.append(package)
        except pkg_resources.VersionConflict:
            # For simplicity, if version conflicts, we append it to upgrade
            missing.append(package)

    if missing:
        print(f"Missing or outdated dependencies found: {', '.join(missing)}")
        print("Installing now...")
        try:
            subprocess.check_call([sys.executable, "-m", "pip", "install"] + missing)
            print("Dependencies installed successfully.")
        except subprocess.CalledProcessError as e:
            print(f"Failed to install dependencies: {e}")
            print("Please install them manually using: pip install -r requirements.txt")
            sys.exit(1)
    else:
        print("All dependencies are satisfied.")"

